def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'
    me = [h[0] for h in history]
    op = [h[1] for h in history]
    my_c = 0
    op_c = 0
    for a in me:
        if a == 'C':
            my_c += 1
    for a in op:
        if a == 'C':
            op_c += 1
    if op_c >= n - max(1, n // 10):
        if op[-1] == 'D':
            return 'D'
        return 'C'
    if op_c <= n // 3:
        if me[-1] == 'D' and op[-1] == 'D':
            return 'C'
        if op[-1] == 'D':
            return 'D'
        return 'C'
    last_me = me[-1]
    last_op = op[-1]
    if last_op == 'D':
        if last_me == 'D':
            return 'C'
        if rng.random() < 0.15:
            return 'C'
        return 'D'
    if n > 85:
        return 'D' if rng.random() < 0.35 else 'C'
    return 'C'
